import{_ as a,o as t,c as i,a2 as e}from"./chunks/framework.Dkj3JE0_.js";const _=JSON.parse('{"title":"ビジネスドイツ語計画","description":"","frontmatter":{"title":"ビジネスドイツ語計画"},"headers":[],"relativePath":"jp/blogs/German/plan.md","filePath":"jp/blogs/German/plan.md"}'),r={name:"jp/blogs/German/plan.md"};function o(d,l,h,n,s,u){return t(),i("div",null,[...l[0]||(l[0]=[e('<h1 id="ビジネスドイツ語-学習計画" tabindex="-1">ビジネスドイツ語 学習計画 <a class="header-anchor" href="#ビジネスドイツ語-学習計画" aria-label="Permalink to &quot;ビジネスドイツ語 学習計画&quot;">​</a></h1><blockquote><p><strong>前提：</strong> 試験のない実用目的の目標で、1 週あたり約 <strong>4 時間</strong>。最初のサイクルは 24 週間で、教科書を広く網羅するよりも、職場で繰り返し出会う場面を優先する。</p></blockquote><h2 id="完了の定義" tabindex="-1">完了の定義 <a class="header-anchor" href="#完了の定義" aria-label="Permalink to &quot;完了の定義&quot;">​</a></h2><p>サイクルの終わりには、無理なく次のことができる：</p><ul><li>自分の役割、経歴、プロジェクト、現在の優先事項を紹介する；</li><li>30 分の会議に参加し、確認の質問をし、決定事項をまとめる；</li><li>明確なメール、フォローアップ、進捗報告、丁寧な反対意見を書く；</li><li>5–7 分のプレゼンテーションを行い、予想される質問に答える；</li><li>英語に切り替えずに、短いネットワーキングや面接の会話をこなす。</li></ul><h2 id="週のリズム" tabindex="-1">週のリズム <a class="header-anchor" href="#週のリズム" aria-label="Permalink to &quot;週のリズム&quot;">​</a></h2><table tabindex="0"><thead><tr><th>セッション</th><th style="text-align:right;">時間</th><th>内容</th></tr></thead><tbody><tr><td>インプット 2 回</td><td style="text-align:right;">各 35 分</td><td>職場のドイツ語を読む・聞く。単語ではなく使えるフレーズを集める。</td></tr><tr><td>アウトプット 2 回</td><td style="text-align:right;">各 35 分</td><td>メールや進捗メモを書き、口頭の回答を録音する。</td></tr><tr><td>会話 1 回</td><td style="text-align:right;">45–60 分</td><td>その月の職場シナリオを、添削付きでロールプレイする。</td></tr><tr><td>復習 1 回</td><td style="text-align:right;">25 分</td><td>直してもらったフレーズを使い直し、ミスの記録を更新する。</td></tr></tbody></table><p><strong>機能別のフレーズバンク</strong>を作る：切り出し、確認、賛成、反対、提案、保留、要約、締めくくり。</p><h2 id="_24-週間のロードマップ" tabindex="-1">24 週間のロードマップ <a class="header-anchor" href="#_24-週間のロードマップ" aria-label="Permalink to &quot;24 週間のロードマップ&quot;">​</a></h2><h3 id="_1-か月目-—-仕事上の自己紹介" tabindex="-1">1 か月目 — 仕事上の自己紹介 <a class="header-anchor" href="#_1-か月目-—-仕事上の自己紹介" aria-label="Permalink to &quot;1 か月目 — 仕事上の自己紹介&quot;">​</a></h3><ul><li>自己紹介、担当業務、チーム構成、キャリアの経歴。</li><li>主な成果物：自然な 90 秒の自己紹介と、文章のプロフィール。</li><li>文法の補強：語順、よく使う前置詞の後の格、過去の出来事の語り方。</li></ul><h3 id="_2-か月目-—-メールとメッセージ" tabindex="-1">2 か月目 — メールとメッセージ <a class="header-anchor" href="#_2-か月目-—-メールとメッセージ" aria-label="Permalink to &quot;2 か月目 — メールとメッセージ&quot;">​</a></h3><ul><li>依頼、日程調整、フォローアップ、添付、締め切り、トーン。</li><li>主な成果物：再利用できるメールの型を 5 つ作り、それぞれ実際の場面に当てはめる。</li><li>凝った儀礼表現よりも、簡潔な文と丁寧な話法の助動詞を重視する。</li></ul><h3 id="_3-か月目-—-会議" tabindex="-1">3 か月目 — 会議 <a class="header-anchor" href="#_3-か月目-—-会議" aria-label="Permalink to &quot;3 か月目 — 会議&quot;">​</a></h3><ul><li>議題の言い回し、発言の順番、確認、意見、反対、決定。</li><li>主な成果物：15 分の模擬会議の進行役を務め、終了後に議事のまとめを送る。</li><li>立場とアクションアイテムを聞き取り、訳すのではなく言い換える。</li></ul><h3 id="_4-か月目-—-プロジェクトと問題解決" tabindex="-1">4 か月目 — プロジェクトと問題解決 <a class="header-anchor" href="#_4-か月目-—-プロジェクトと問題解決" aria-label="Permalink to &quot;4 か月目 — プロジェクトと問題解決&quot;">​</a></h3><ul><li>進捗、依存関係、リスク、遅延、トレードオフ、データ、提言。</li><li>主な成果物：リスクと依頼を 1 つずつ含む、毎週 2 分のプロジェクト報告。</li><li>すべての文を台本にせずに、グラフや数字を説明する練習をする。</li></ul><h3 id="_5-か月目-—-プレゼンテーションと説得" tabindex="-1">5 か月目 — プレゼンテーションと説得 <a class="header-anchor" href="#_5-か月目-—-プレゼンテーションと説得" aria-label="Permalink to &quot;5 か月目 — プレゼンテーションと説得&quot;">​</a></h3><ul><li>道しるべの言葉、比較、強調、根拠、質問、反論。</li><li>主な成果物：ポートフォリオのプロジェクト 1 つについて、5–7 分のプレゼンを録画する。</li><li>暗記ではなく、話し方が安定するまでフィードバック後に繰り返す。</li></ul><h3 id="_6-か月目-—-統合" tabindex="-1">6 か月目 — 統合 <a class="header-anchor" href="#_6-か月目-—-統合" aria-label="Permalink to &quot;6 か月目 — 統合&quot;">​</a></h3><ul><li>ネットワーキング、面接、交渉、異文化の職場シナリオ。</li><li>主な成果物：雑談からプロジェクトの議論、フォローアップメールまでを通す 30 分のシミュレーション。</li><li>一般的なレベル表ではなく、実際につまずいた点から次のサイクルを決める。</li></ul><h2 id="月次のフィードバック・ループ" tabindex="-1">月次のフィードバック・ループ <a class="header-anchor" href="#月次のフィードバック・ループ" aria-label="Permalink to &quot;月次のフィードバック・ループ&quot;">​</a></h2><p>毎月の終わりに、4 つの成果物を残す：</p><ol><li>添削済みのメール 1 通；</li><li>録音したスピーキング課題 1 つ；</li><li>繰り返し起きるミス 5 つのリスト；</li><li>複数の場面で使えた価値の高いフレーズ 10 個。</li></ol><p>正確さだけでなく、<strong>コミュニケーションが成功したか</strong>を記録する：相手は依頼、決定、リスク、次のアクションを理解したか？</p><h2 id="最初の-7-日間" tabindex="-1">最初の 7 日間 <a class="header-anchor" href="#最初の-7-日間" aria-label="Permalink to &quot;最初の 7 日間&quot;">​</a></h2><ul><li>[ ] ノートなしで 2 分間の自己紹介を録音する。</li><li>[ ] 実際にありそうな仕事のメールを 1 通書き、添削してもらう。</li><li>[ ] 機能別フレーズバンクとミスの記録を作る。</li><li>[ ] 毎週の会話練習またはチューターの枠を予約する。</li><li>[ ] 6 か月のスピーキング・ポートフォリオの題材にする実際のプロジェクトを 1 つ選ぶ。</li></ul>',27)])])}const b=a(r,[["render",o]]);export{_ as __pageData,b as default};
